/**
 * Arabic tags, descriptions, root classes, the closed-class table and the pattern guess (src/adapters/arabic/{tags,describe,roots,closed,guess,paradigm}.ts).
 * Rows are the Wiktionary tag bundles of the mini fixture (test/adapters/arabic-mini-index.json, generated by scripts/ar-mini-index.mts).
 */
import fs from 'node:fs';
import { describe, expect, it } from 'vitest';
import { AR_CLOSED, AR_PRIORS, arClosedFor } from '../../src/adapters/arabic/closed';
import { describeArMorph } from '../../src/adapters/arabic/describe';
import { arGuess } from '../../src/adapters/arabic/guess';
import { arCellsFor } from '../../src/adapters/arabic/paradigm';
import { rootClass, rootInfo } from '../../src/adapters/arabic/roots';
import { arFeaturesFromTableTags, arFeaturesOfCode, arMorphFromTags, arUnknownTags, resetArUnknownTags } from '../../src/adapters/arabic/tags';
import { arKey } from '../../src/adapters/arabic/text';
import type { ArabicFormIndex } from '../../src/adapters/arabic/index-store';

const fixture = JSON.parse(fs.readFileSync(new URL('./arabic-mini-index.json', import.meta.url), 'utf8')) as ArabicFormIndex;
const f = (code: string, pos: string, lex = ''): Record<string, string> => arFeaturesOfCode(code, pos, lex).morph;

describe('arFeaturesOfCode: the source labels become features', () => {
  it('a perfect 3rd person masculine singular active: Aspect=Perf, Mood=Ind, Voice=Act, Person=3, Gender=Masc, Number=Sing, Form from the lexeme', () => {
    expect(f('active|indicative|masculine|past|perfective|singular|third-person', 'VERB', 'Form=I')).toEqual({
      Aspect: 'Perf', Mood: 'Ind', Voice: 'Act', Person: '3', Gender: 'Masc', Number: 'Sing', VerbForm: 'Fin', Form: 'I',
    });
  });
  it('an imperfect row: Aspect=Imp from non-past; the three moods are three codes', () => {
    expect(f('active|imperfective|indicative|masculine|non-past|singular|third-person', 'VERB').Aspect).toBe('Imp');
    expect(f('active|imperfective|jussive|masculine|non-past|singular|third-person', 'VERB').Mood).toBe('Jus');
    expect(f('active|imperfective|masculine|non-past|singular|subjunctive|third-person', 'VERB').Mood).toBe('Sub');
  });
  it('J5: a row that names only a mood (no past / non-past tag) is the imperfect: Aspect=Imp, also for passives; the imperative has none', () => {
    expect(f('active|indicative|third-person|plural|feminine', 'VERB').Aspect).toBe('Imp');
    expect(f('indicative|passive|singular|third-person|masculine', 'VERB').Aspect).toBe('Imp');
    expect(f('active|imperative|masculine|second-person|singular', 'VERB').Aspect).toBeUndefined();
    expect(f('active|imperative|masculine|second-person|singular', 'VERB').Mood).toBe('Imp');
  });
  it('energetic is Mood=Ene', () => { expect(f('active|energetic|third-person|singular|masculine', 'VERB').Mood).toBe('Ene'); });
  it('a noun: case, definiteness, number, declension, the lexeme gender', () => {
    expect(f('accusative|indefinite|singular|triptote', 'NOUN', 'Gender=Masc')).toEqual({ Case: 'Acc', Definite: 'Ind', Number: 'Sing', Decl: 'Trip', Gender: 'Masc' });
    expect(f('construct|genitive|singular|triptote', 'NOUN').Definite).toBe('Cons');
  });
  it('the dual cells of a noun carry "dual" and "singular": the number is Dual; a first-person "dual|plural" cell is Plur', () => {
    expect(f('dual|indefinite|nominative|singular|triptote', 'NOUN').Number).toBe('Dual');
    expect(f('dual|first-person|plural', 'ADP').Number).toBe('Plur');
  });
  it('plural types and the pausal form: the "informal" row has no case', () => {
    expect(f('broken-form|indefinite|nominative|plural|triptote', 'NOUN').PluralType).toBe('Broken');
    expect(f('indefinite|nominative|plural|sound-form', 'NOUN').PluralType).toBe('Sound');
    const p = f('indefinite|informal|singular|triptote', 'NOUN');
    expect(p.Pausal).toBe('Yes');
    expect(p.Case).toBeUndefined();
  });
  it('participles and verbal nouns under a verb: VerbForm=Part / Vnoun, no person, mood or aspect', () => {
    expect(f('active|participle', 'VERB', 'Form=I')).toEqual({ VerbForm: 'Part', Voice: 'Act', Form: 'I' });
    expect(f('participle|passive', 'VERB').Voice).toBe('Pass');
    expect(f('noun-from-verb', 'VERB').VerbForm).toBe('Vnoun');
  });
  it('J9: an elative has only its one form: Degree=Cmp,Sup', () => { expect(f('elative', 'ADJ').Degree).toBe('Cmp,Sup'); });
  it('class markers and register labels are not features; register labels come back as usage', () => {
    const r = arFeaturesOfCode('ar-infl-a|dialectal|indefinite|informal|singular|triptote', 'NOUN', '');
    expect(r.usage).toEqual(['dialectal']);
    expect(Object.keys(r.morph).sort()).toEqual(['Decl', 'Definite', 'Number', 'Pausal']);
  });
  it('every label of the fixture rows is known to the reader (none is silently dropped)', () => {
    resetArUnknownTags();
    for (const code of fixture.codes) arFeaturesOfCode(code, 'NOUN', '');
    expect(arUnknownTags()).toEqual([]);
  });
  it('arMorphFromTags takes a list or a bundle', () => {
    expect(arMorphFromTags(['plural', 'masculine'])).toEqual({ Number: 'Plur', Gender: 'Masc' });
    expect(arMorphFromTags('feminine|singular')).toEqual({ Gender: 'Fem', Number: 'Sing' });
  });
  it('arFeaturesFromTableTags: a cell is a feature set; the template rows and error rows are not cells', () => {
    expect(arFeaturesFromTableTags(['genitive', 'definite', 'singular', 'triptote'], 'NOUN')).toEqual({ Case: 'Gen', Definite: 'Def', Number: 'Sing' });
    expect(arFeaturesFromTableTags(['table-tags'], 'NOUN')).toBeUndefined();
    expect(arFeaturesFromTableTags(['error-unrecognized-form', 'masculine'], 'ADP')).toBeUndefined();
    expect(arFeaturesFromTableTags(['active', 'participle'], 'VERB')?.VerbForm).toBe('Part');
  });
});

describe('describeArMorph: plain English for a learner', () => {
  it('a perfect verb says "perfect (completed action)", never "past tense"', () => {
    const d = describeArMorph(f('active|indicative|masculine|past|perfective|singular|third-person', 'VERB', 'Form=I'), 'VERB');
    expect(d).toContain('perfect (completed action), 3rd person masculine singular, active');
    expect(d).not.toMatch(/past tense|present tense/);
  });
  it('an imperfect verb says "imperfect" and names the mood: indicative, subjunctive, jussive', () => {
    expect(describeArMorph({ Aspect: 'Imp', Mood: 'Sub', Person: '3', Gender: 'Masc', Number: 'Sing', Voice: 'Act', VerbForm: 'Fin' }, 'VERB')).toMatch(/imperfect.*subjunctive/);
    expect(describeArMorph({ Aspect: 'Imp', Mood: 'Jus', Person: '3', Gender: 'Masc', Number: 'Sing', Voice: 'Act', VerbForm: 'Fin' }, 'VERB')).toContain('jussive');
  });
  it('the union Person=2,3 is told as the two cells: "you (m. sg.) or she"', () => {
    const d = describeArMorph({ Aspect: 'Imp', Mood: 'Ind', Person: '2,3', Gender: 'Fem,Masc', Number: 'Sing', Voice: 'Act', VerbForm: 'Fin' }, 'VERB');
    expect(d).toContain('you (m. sg.) or she');
  });
  it('a noun: part of speech, case, definiteness; the construct state is named', () => {
    expect(describeArMorph({ Case: 'Gen', Definite: 'Def' }, 'NOUN')).toBe('noun, genitive, definite');
    expect(describeArMorph({ Case: 'Nom', Definite: 'Cons', Number: 'Sing' }, 'NOUN')).toContain('construct state');
  });
  it('participles, verbal nouns and imperatives', () => {
    expect(describeArMorph({ VerbForm: 'Part', Voice: 'Act', Form: 'I' }, 'ADJ')).toBe('active participle, form I');
    expect(describeArMorph({ VerbForm: 'Vnoun' }, 'NOUN')).toBe('verbal noun');
    expect(describeArMorph({ VerbForm: 'Fin', Mood: 'Imp', Person: '2', Gender: 'Masc', Number: 'Sing', Voice: 'Act' }, 'VERB')).toMatch(/^imperative, 2nd person masculine singular/);
  });
  it('a pausal form says so', () => { expect(describeArMorph({ Pausal: 'Yes', Number: 'Sing' }, 'NOUN')).toContain('without its ending'); });
});

describe('rootClass: from the radicals only', () => {
  const cls = (r: string): string => rootClass(r);
  it('sound, assimilated, hollow, defective, geminate, hamzated, doubly weak, quadriliteral', () => {
    expect(cls('ك ت ب')).toBe('sound');
    expect(cls('و ع د')).toBe('assimilated');
    expect(cls('ق و ل')).toBe('hollow');
    expect(cls('ب ي ع')).toBe('hollow');
    expect(cls('ر م ي')).toBe('defective');
    expect(cls('د ع و')).toBe('defective');
    expect(cls('م د د')).toBe('geminate');
    expect(cls('ء ك ل')).toBe('hamzated');
    expect(cls('و ف ي')).toBe('doubly-weak');
    expect(cls('ر ء ي')).toContain('hamzated');
    expect(cls('ز ل ز ل')).toBe('quadriliteral');
  });
  it('no root, no class', () => { expect(cls('')).toBe(''); expect(rootInfo(undefined).classes).toEqual([]); });
});

describe('closed-class table (machine-drafted)', () => {
  it('has the particles, pronouns, demonstratives, relatives and interrogatives, keyed by the unvocalized key', () => {
    for (const w of ['وَ', 'فَ', 'ثُمَّ', 'أَوْ', 'بَلْ', 'فِي', 'مِنْ', 'إِلَى', 'عَلَى', 'عَنْ', 'لَنْ', 'لَمْ', 'لَا', 'قَدْ', 'سَوْفَ', 'هَلْ', 'إِذَا', 'لَوْ', 'حَتَّى', 'كَيْ', 'لٰكِنَّ', 'أَنَا', 'هُوَ', 'هٰذَا', 'ذٰلِكَ', 'الَّذِي', 'مَاذَا', 'كَيْفَ'])
      expect(arClosedFor(arKey(w)).length, w).toBeGreaterThan(0);
  });
  it('says what a particle governs: لَنْ the subjunctive, لَمْ the jussive, إِنَّ an accusative subject, مِنْ the genitive', () => {
    expect(arClosedFor('لن')[0].governs).toBe('subjunctive');
    expect(arClosedFor('لم').find((e) => e.lemma === 'لَمْ')?.governs).toBe('jussive');
    expect(arClosedFor('إن').find((e) => e.lemma === 'إِنَّ')?.governs).toBe('accusative subject');
    expect(arClosedFor('من').find((e) => e.pos === 'ADP')?.governs).toBe('genitive');
  });
  it('prepositions with pronoun suffixes whose spelling changes are listed with their pronoun: لَهُ بِهِ عَلَيْهِ إِلَيْهِ فِيهِ مِنْهُ عَنْهُ لِي لَدَيْهِ مَعَهُ', () => {
    for (const w of ['لَهُ', 'بِهِ', 'عَلَيْهِ', 'إِلَيْهِ', 'فِيهِ', 'مِنْهُ', 'عَنْهُ', 'لِي', 'لَدَيْهِ', 'مَعَهُ']) {
      const e = arClosedFor(arKey(w)).find((x) => x.suffix);
      expect(e, w).toBeDefined();
      expect(e!.pos).toBe('ADP');
      expect(e!.morph.Person, w).toBeDefined();
    }
    expect(arClosedFor('له')[0].lemma).toBe('لِ');
    expect(arClosedFor('عليه')[0].lemma).toBe('عَلَى');
    expect(arClosedFor('لي')[0].morph).toEqual({ Person: '1', Number: 'Sing' });
  });
  it('fused particles are entries, not cuts (مما عما فيما إلام ألا لئلا كيلا إنما) and the -ئذ forms are entries', () => {
    for (const w of ['مِمَّا', 'عَمَّا', 'فِيمَا', 'إِلَامَ', 'أَلَّا', 'لِئَلَّا', 'كَيْلَا', 'إِنَّمَا', 'حِينَئِذٍ', 'يَوْمَئِذٍ']) expect(arClosedFor(arKey(w)).length, w).toBeGreaterThan(0);
    expect(arClosedFor('مما')[0].fusedOf).toBe('مِنْ + مَا');
  });
  it('the vocative يا written onto the next word (يأيها) is one entry', () => { expect(arClosedFor(arKey('يَاأَيُّهَا'))[0].fusedOf).toContain('يَا'); });
  it('hand priors name the dominant reading of a closed-class homograph (مِنْ over مَنْ)', () => {
    expect(AR_PRIORS['من'].lemma).toBe('مِنْ');
    expect(AR_PRIORS['في'].pos).toEqual(['ADP']);
    expect(Object.keys(AR_CLOSED).length).toBeGreaterThan(150);
  });
});

describe('arGuess: a marked guess from an unmistakable pattern only', () => {
  it('a sound feminine plural -ات of an unknown noun', () => {
    const g = arGuess('سيارات');
    expect(g).toHaveLength(1);
    expect(g[0].pos).toBe('NOUN');
    expect(g[0].morph).toMatchObject({ Number: 'Plur', PluralType: 'Sound' });
  });
  it('with the article it adds Definite=Def; short words, other endings and non-Arabic text give nothing', () => {
    expect(arGuess('السيارات')[0].morph.Definite).toBe('Def');
    expect(arGuess('بات')).toEqual([]);
    expect(arGuess('كتابان')).toEqual([]);
    expect(arGuess('abcات')).toEqual([]);
  });
});

describe('arCellsFor: the dictionary table cells of a reading', () => {
  it('the features name the cells; the form is compared without its vowels', () => {
    const cells = [
      { form: 'الْكِتَابُ', features: { Case: 'Nom', Definite: 'Def', Number: 'Sing' } },
      { form: 'الْكِتَابَ', features: { Case: 'Acc', Definite: 'Def', Number: 'Sing' } },
    ] as never;
    const p = { cells, kind: 'noun', pos: 'NOUN' } as never;
    const got = arCellsFor(p, { Case: 'Acc,Nom', Definite: 'Def', Number: 'Sing' }, 'الكتاب');
    expect(got.length).toBeGreaterThan(0);
  });
});
